"""Parallel helpers for pandas GroupBy objects."""

from __future__ import annotations

from functools import wraps

from pandas import Series, option_context
from pandas.core.groupby.generic import DataFrameGroupBy, SeriesGroupBy
from pandas.core.groupby.ops import _is_indexed_like

from ..core import run_parallel_jobs
from .generic import monkey_patch


def _group_apply_chunk(group, key, func, axis: int):
    object.__setattr__(group, "name", key)
    axes = group.axes
    result = func(group)
    mutated = not _is_indexed_like(result, axes, axis)
    return result, mutated


def _parallel_groupby_apply(groupby, func, data):
    splitter = groupby._grouper._get_splitter(data, axis=groupby.axis)
    group_keys = list(groupby._grouper.group_keys_seq)
    groups = list(splitter)

    if len(groups) <= 1:
        values = []
        mutated = False
        for key, group in zip(group_keys, groups):
            result, changed = _group_apply_chunk(group, key, func, groupby.axis)
            values.append(result)
            mutated = mutated or changed
        return groupby._wrap_applied_output(data, values, mutated, False)

    jobs = [
        (_group_apply_chunk, (group, key, func, groupby.axis), {})
        for key, group in zip(group_keys, groups)
    ]

    applied = run_parallel_jobs(jobs, progress_label=f"{type(groupby).__name__}.apply")
    values = [result for result, _ in applied]
    mutated = any(changed for _, changed in applied)
    return groupby._wrap_applied_output(data, values, mutated, False)


def parallel_apply(self, func, *args, **kwargs):
    if isinstance(func, str) or not callable(func):
        return self.apply(func, *args, **kwargs)

    include_groups = kwargs.pop("include_groups", True)

    if args or kwargs:
        @wraps(func)
        def wrapped(group):
            return func(group, *args, **kwargs)
    else:
        wrapped = func

    if not include_groups:
        return _parallel_groupby_apply(self, wrapped, self._obj_with_exclusions)

    with option_context("mode.chained_assignment", None):
        try:
            return _parallel_groupby_apply(self, wrapped, self._selected_obj)
        except TypeError:
            if isinstance(self.obj, Series):
                raise
            return _parallel_groupby_apply(self, wrapped, self._obj_with_exclusions)


def patch_groupby() -> None:
    monkey_patch(DataFrameGroupBy, "parallel_apply", parallel_apply)
    monkey_patch(SeriesGroupBy, "parallel_apply", parallel_apply)

