"""Minimal progress bar utilities."""

from __future__ import annotations

import math
import sys
import threading
from dataclasses import dataclass, field


@dataclass
class ProgressBar:
    """A lightweight terminal progress bar."""

    total: int
    enabled: bool = False
    label: str = "pandarallel"
    stream: object = sys.stderr
    _count: int = 0
    _lock: threading.Lock = field(default_factory=threading.Lock)

    def update(self, step: int = 1) -> None:
        if not self.enabled or self.total <= 0:
            return

        with self._lock:
            self._count = min(self.total, self._count + step)
            self._render()

    def close(self) -> None:
        if not self.enabled or self.total <= 0:
            return

        with self._lock:
            self._count = self.total
            self._render(done=True)

    def _render(self, done: bool = False) -> None:
        width = 30
        ratio = self._count / self.total if self.total else 1.0
        filled = min(width, math.floor(width * ratio))
        bar = "#" * filled + "-" * (width - filled)
        message = f"\r{self.label} [{bar}] {self._count}/{self.total}"
        if done:
            message += "\n"
        self.stream.write(message)
        self.stream.flush()


class NullProgressBar(ProgressBar):
    """No-op progress bar used when output is disabled."""

    def __init__(self) -> None:
        super().__init__(total=0, enabled=False, label="")

    def update(self, step: int = 1) -> None:  # noqa: ARG002
        return

    def close(self) -> None:
        return


def create_progress_bar(total: int, enabled: bool, label: str) -> ProgressBar:
    """Create an enabled or disabled progress bar."""

    if enabled and total > 0:
        return ProgressBar(total=total, enabled=True, label=label)
    return NullProgressBar()

