from __future__ import annotations

import pandas as pd
from pandas.core.window.expanding import ExpandingGroupby

from ..core import run_parallel_jobs
from .generic import monkey_patch


def _groupby_expanding_apply_chunk(
    group,
    key,
    func,
    expanding_kwargs,
    apply_kwargs,
):
    object.__setattr__(group, "name", key)
    return group.expanding(**expanding_kwargs).apply(func, **apply_kwargs)


def parallel_apply(
    self: ExpandingGroupby,
    func,
    raw: bool = False,
    engine=None,
    engine_kwargs=None,
    args=None,
    kwargs=None,
):
    splitter = self._grouper._get_splitter(self._selected_obj, axis=self.axis)
    group_keys = list(self._grouper.group_keys_seq)
    groups = list(splitter)

    expanding_kwargs = dict(
        min_periods=self.min_periods,
        method=self.method,
    )
    apply_kwargs = dict(
        raw=raw,
        engine=engine,
        engine_kwargs=engine_kwargs,
        args=args,
        kwargs=kwargs,
    )

    if len(groups) <= 1:
        parts = [
            _groupby_expanding_apply_chunk(group, key, func, expanding_kwargs, apply_kwargs)
            for key, group in zip(group_keys, groups)
        ]
    else:
        jobs = [
            (
                _groupby_expanding_apply_chunk,
                (group, key, func, expanding_kwargs, apply_kwargs),
                {},
            )
            for key, group in zip(group_keys, groups)
        ]
        parts = run_parallel_jobs(jobs, progress_label="ExpandingGroupby.apply")

    return pd.concat(parts, keys=group_keys, names=list(self._grouper.names))


def patch_expanding_groupby() -> None:
    monkey_patch(ExpandingGroupby, "parallel_apply", parallel_apply)

