"""Small helpers shared across the project."""

from __future__ import annotations

import os
import tempfile
from typing import Iterable, List

import dill
import psutil


def get_physical_cores() -> int:
    """Return the best available physical core count."""

    count = psutil.cpu_count(logical=False) or os.cpu_count() or 1
    return max(1, int(count))


def normalize_nb_workers(nb_workers: int | None, default: int) -> int:
    """Clamp the configured worker count to a sensible positive integer."""

    if nb_workers is None:
        return max(1, default)

    try:
        value = int(nb_workers)
    except (TypeError, ValueError) as exc:
        raise ValueError("nb_workers must be an integer or None") from exc

    if value < 1:
        raise ValueError("nb_workers must be greater than or equal to 1")

    return value


def normalize_axis(axis: int | str) -> int:
    """Convert pandas axis aliases into 0 or 1."""

    if axis in (0, "index"):
        return 0
    if axis in (1, "columns"):
        return 1
    raise ValueError(f"Unsupported axis: {axis!r}")


def chunk_slices(length: int, requested_chunks: int) -> List[slice]:
    """Split a sequence length into ordered, non-empty slices."""

    if length <= 0:
        return []

    chunks = max(1, min(int(requested_chunks), length))
    base, remainder = divmod(length, chunks)

    slices: List[slice] = []
    start = 0

    for chunk_index in range(chunks):
        stop = start + base + (1 if chunk_index < remainder else 0)
        if stop > start:
            slices.append(slice(start, stop))
        start = stop

    return slices


def is_memory_fs_available(root: str) -> bool:
    """Return True when the configured memory filesystem looks writable."""

    if not root:
        return False

    if not os.path.isdir(root):
        return False

    if not os.access(root, os.W_OK | os.X_OK):
        return False

    try:
        with tempfile.NamedTemporaryFile(dir=root, prefix="pandarallel_", delete=True):
            return True
    except OSError:
        return False


def dump_payload_to_tempfile(payload: bytes, root: str) -> str:
    """Persist serialized work in a temporary file and return its path."""

    handle = tempfile.NamedTemporaryFile(
        dir=root,
        prefix="pandarallel_",
        suffix=".job",
        delete=False,
    )
    try:
        with handle:
            handle.write(payload)
        return handle.name
    except Exception:
        try:
            os.unlink(handle.name)
        except OSError:
            pass
        raise


def serialize_job(function, args: Iterable, kwargs: dict) -> bytes:
    """Serialize a callable job with dill."""

    return dill.dumps((function, tuple(args), dict(kwargs)), recurse=True)

