"""Parallel helpers for pandas DataFrame objects."""

from __future__ import annotations

import pandas as pd

from ..core import get_config, run_parallel_jobs
from ..utils import chunk_slices, normalize_axis
from .generic import monkey_patch


def _dataframe_apply_chunk(
    frame: pd.DataFrame,
    func,
    axis: int,
    raw: bool,
    result_type,
    args,
    by_row,
    engine,
    engine_kwargs,
    kwargs,
):
    return frame.apply(
        func,
        axis=axis,
        raw=raw,
        result_type=result_type,
        args=args,
        by_row=by_row,
        engine=engine,
        engine_kwargs=engine_kwargs,
        **kwargs,
    )


def _dataframe_applymap_chunk(
    frame: pd.DataFrame,
    func,
    na_action,
    kwargs,
):
    if hasattr(frame, "map"):
        return frame.map(func, na_action=na_action, **kwargs)
    return frame.applymap(func, na_action=na_action, **kwargs)


def _combine_apply_parts(parts, axis: int):
    if not parts:
        return pd.Series(dtype="float64")

    first = parts[0]
    if isinstance(first, pd.DataFrame):
        concat_axis = 1 if axis == 0 else 0
        return pd.concat(parts, axis=concat_axis)
    return pd.concat(parts, axis=0)


def parallel_apply(
    self: pd.DataFrame,
    func,
    axis=0,
    raw: bool = False,
    result_type=None,
    args=(),
    by_row="compat",
    engine="python",
    engine_kwargs=None,
    **kwargs,
):
    axis = normalize_axis(axis)
    config = get_config()
    length = self.shape[0] if axis == 1 else self.shape[1]
    slices = chunk_slices(length, config.nb_workers)

    if len(slices) <= 1:
        return self.apply(
            func,
            axis=axis,
            raw=raw,
            result_type=result_type,
            args=args,
            by_row=by_row,
            engine=engine,
            engine_kwargs=engine_kwargs,
            **kwargs,
        )

    jobs = []
    for item in slices:
        chunk = self.iloc[item, :] if axis == 1 else self.iloc[:, item]
        jobs.append(
            (
                _dataframe_apply_chunk,
                (
                    chunk,
                    func,
                    axis,
                    raw,
                    result_type,
                    args,
                    by_row,
                    engine,
                    engine_kwargs,
                    kwargs,
                ),
                {},
            )
        )

    parts = run_parallel_jobs(jobs, progress_label="DataFrame.apply")
    return _combine_apply_parts(parts, axis)


def parallel_applymap(
    self: pd.DataFrame,
    func,
    na_action=None,
    **kwargs,
):
    config = get_config()
    slices = chunk_slices(len(self.index), config.nb_workers)

    if len(slices) <= 1:
        return _dataframe_applymap_chunk(self, func, na_action, kwargs)

    jobs = [
        (
            _dataframe_applymap_chunk,
            (self.iloc[item, :], func, na_action, kwargs),
            {},
        )
        for item in slices
    ]

    parts = run_parallel_jobs(jobs, progress_label="DataFrame.applymap")
    return pd.concat(parts, axis=0)


def patch_dataframe() -> None:
    monkey_patch(pd.DataFrame, "parallel_apply", parallel_apply)
    monkey_patch(pd.DataFrame, "parallel_applymap", parallel_applymap)

